Final output schema: {"$defs": {"HedgePlanV2": {"additionalProperties": false, "properties": {"objective": {"title": "Objective", "type": "string"}, "target_hedge_ratio": {"title": "Target Hedge Ratio", "type": "string"}, "main_position_id": {"title": "Main Position Id", "type": "string"}, "hedge_position_id": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Hedge Position Id"}, "ratio_basis": {"const": "absolute_mark_notional", "title": "Ratio Basis", "type": "string"}, "expected_effect_on_exposure": {"title": "Expected Effect On Exposure", "type": "string"}, "costs": {"items": {"type": "string"}, "minItems": 1, "title": "Costs", "type": "array"}, "unlock_condition": {"title": "Unlock Condition", "type": "string"}, "failure_condition": {"title": "Failure Condition", "type": "string"}}, "required": ["objective", "target_hedge_ratio", "main_position_id", "hedge_position_id", "ratio_basis", "expected_effect_on_exposure", "costs", "unlock_condition", "failure_condition"], "title": "HedgePlanV2", "type": "object"}, "ManagementEvidence": {"additionalProperties": false, "properties": {"observations": {"items": {"type": "string"}, "minItems": 1, "title": "Observations", "type": "array"}, "evidence_for": {"items": {"type": "string"}, "minItems": 1, "title": "Evidence For", "type": "array"}, "evidence_against": {"items": {"type": "string"}, "minItems": 1, "title": "Evidence Against", "type": "array"}}, "required": ["observations", "evidence_for", "evidence_against"], "title": "ManagementEvidence", "type": "object"}, "ManagementExecution": {"additionalProperties": false, "properties": {"orders": {"items": {}, "maxItems": 0, "title": "Orders", "type": "array"}, "cancel_order_ids": {"items": {}, "maxItems": 0, "title": "Cancel Order Ids", "type": "array"}, "replace_orders": {"items": {}, "maxItems": 0, "title": "Replace Orders", "type": "array"}}, "required": ["orders", "cancel_order_ids", "replace_orders"], "title": "ManagementExecution", "type": "object"}, "Managem